def file_name_check(file_name):
    if len(file_name.split('.')[-1]) not in ['txt', 'exe', 'dll']:
        return 'No'
    if file_name.split('.')[0][0].isdigit() or not file_name.split('.')[0][0].isalpha():
        return 'No'
    if len(file_name.split('.')) < 2:
        return 'No'
    if file_name.count('.') != 1:
        return 'No'
    if len([char for char in file_name.split('.')[-2] if char.isdigit()] > 3):
        return 'No'
    return 'Yes'
